import java.util.*;class Solution{String[]m={"","","abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"};List<String>o=new ArrayList<>();void bt(String d,int i,StringBuilder c){if(i==d.length()){o.add(c.toString());return;}for(char x:m[d.charAt(i)-'0'].toCharArray()){c.append(x);bt(d,i+1,c);c.deleteCharAt(c.length()-1);}}public List<String> letterCombinations(String d){if(d.isEmpty())return o;bt(d,0,new StringBuilder());return o;}}
